  const gx = bx1 - wall * 4;
  for (let x = gx - short * 0.09; x < gx + short * 0.09; x++) {
    const top = Math.round(dune(Math.round(x)));
    for (let y = top - Math.round(short * 0.03); y < top; y++) put(x, y, PLANT, 60 + Math.floor(Math.random() * 40));
