const fs = `#version 300 es
precision highp float;
out vec4 outColor;
uniform vec2 u_resolution;
uniform float u_tick;
uniform vec2 u_grid;
uniform sampler2D u_cells, u_smoke;
${ctx.utils.glsl.SIMPLEX_3D}
${ctx.utils.glsl.COLOR_SPACE}
// sandspiel's sand.glsl: one hue/saturation/value recipe per species from (type, ra, rb).
void main() {
  vec2 pix = vec2(gl_FragCoord.x, u_resolution.y - gl_FragCoord.y);
  vec2 cellf = pix / u_resolution * u_grid;
  ivec2 cell = ivec2(clamp(floor(cellf), vec2(0.0), u_grid - 1.0));
  vec4 data = texelFetch(u_cells, ivec2(cell.y, cell.x), 0);
  int type = int(data.r * 255.0 + 0.1);
