  vec2 grain = floor(cellf * 2.0);
  float noise = snoise(vec3(grain, u_tick * 0.05));
  if (type == 0) { hue = 0.0; saturation = 0.1; lightness = 0.1; a = 0.1; }
  else if (type == 1) { hue = 0.1; saturation = 0.1; lightness = 0.4; }
  else if (type == 2) { hue = 0.1; saturation = 0.5; lightness += 0.3; }
  else if (type == 3) { hue = 0.6; lightness = 0.7 + data.g * 0.25 + noise * 0.1; if (int(mod(data.g * 255.0, 2.0) + 0.1) == 0) lightness += 0.01; }
  else if (type == 4) { hue = 0.0; lightness += 0.4; saturation = 0.2 + data.b * 1.5; }
  else if (type == 5) { hue = 0.9; saturation = 0.3; }
  else if (type == 6) { hue = data.g * 0.1; saturation = 0.7; lightness = 0.7 + data.g * 0.3 + (noise + 0.8) * 0.5; }
  else if (type == 7) { hue = data.g * 0.1; saturation = 0.3; lightness = 0.3 + data.g * 0.3; }
  else if (type == 8) { hue = data.g * 0.1; lightness = 0.7 + data.g * 0.25 + noise * 0.1; }
  else if (type == 9) { hue = 0.6; saturation = 0.4; lightness = 0.7 + data.g * 0.5; }
  else if (type == 11) { hue = 0.4; saturation = 0.4; }
  else if (type == 12) { hue = 0.18; saturation = 0.9; lightness = 0.8 + data.g * 0.2 + noise * 0.05; }
  else if (type == 13) { hue = -0.4 + data.g * 0.5; saturation = 0.1; }
  else if (type == 14) { hue = data.g * 2.0 + u_tick * 0.0008; saturation = 0.4; lightness = 0.8; }
  else if (type == 15) { hue = 0.8; saturation = 0.9; lightness = 0.8; }
  else if (type == 16) { hue = data.g * 5.0 + u_tick * 0.008; saturation = 0.2; lightness = 0.3; }
  else if (type == 17) { hue = 0.0; saturation = 0.4 + data.b; lightness = 0.9; }
  else if (type == 18) { hue = data.g * 0.15 - 0.1; saturation = data.g * 0.8 - 0.05; lightness = 1.5 - data.g * 0.2; }
  else if (type == 19) { hue = fract(fract(data.b * 2.0) * 0.5) - 0.3; saturation = 0.7 * (data.g + 0.4) + data.b * 0.2; lightness = 0.9 * (data.g + 0.9); }
