gl.useProgram(s.prog);
ctx.utils.bindTexture(s.prog, "u_cells", s.tex, 0);
ctx.utils.bindTexture(s.prog, "u_smoke", s.smokeTex, 1);
ctx.utils.drawFullscreen(s.prog, { u_tick: ctx.frame, u_grid: [S.GW, S.GH] });
ctx.publish("grid", `${S.GW}×${S.GH}`);
